import pandas as pd,numpy as np,json,math,itertools
d=pd.read_csv(\"respondents.csv\")
P=[4,7,10,13]; pairs=list(itertools.combinations(range(4),2)); z=1.959963984540054
def base(a):
 w=a.wt_design.to_numpy(); return [len(a),round(w.sum(),6),round(w.sum()**2/(w@w),6)]
def stat(a):
 w=a.wt_design.to_numpy(); y=a.intent_5.isin([4,5]).to_numpy(); q=w@y/w.sum(); v=len(a)/(len(a)-1)*sum(w*w*(y-q)**2)/w.sum()**2; return q,v
def ci(q,v):return [q-z*math.sqrt(v),q+z*math.sqrt(v)]
def tests(entries):
 out=[]
 for q,v in entries:out.append([q,ci(q,v),math.erfc(abs(q/math.sqrt(v))/math.sqrt(2))])
 order=np.argsort([a[2] for a in out]); prev=0
 for rank,i in enumerate(order):
  prev=max(prev,min(1,(len(out)-rank)*out[i][2]));out[i].append(prev)
 return out
arms=[d[d.assigned_price_gbp==p] for p in P]; valid=[a[a.intent_5.isin(range(1,6))] for a in arms]
qv=np.array([stat(a)[0] for a in valid]); vv=np.array([stat(a)[1] for a in valid]); q0=np.array([stat(a)[0] for a in arms]); v0=np.array([stat(a)[1] for a in arms])
out={}
out[\"bases\"]=[{\"assigned\":base(a),\"eligible\":base(a[a.postprice_responded==1]),\"valid\":base(b),\"distribution\":[100*b.loc[b.intent_5==k,\"wt_design\"].sum()/b.wt_design.sum() for k in range(1,6)],\"missing_n\":[int(a.intent_5.isna().sum())]+[int((a.intent_5==k).sum()) for k in [97,98,99]],\"missing_pct\":[100*a.loc[a.intent_5.isna(),\"wt_design\"].sum()/a.wt_design.sum()]+[100*a.loc[a.intent_5==k,\"wt_design\"].sum()/a.wt_design.sum() for k in [97,98,99]]} for a,b in zip(arms,valid)]
out[\"qv\"]=qv.tolist();out[\"qv_ci\"]=[ci(q,v) for q,v in zip(qv,vv)];out[\"q0\"]=q0.tolist();out[\"q0_ci\"]=[ci(q,v) for q,v in zip(q0,v0)]
for name,q,v in [(\"P1\",qv,vv),(\"P2\",q0,v0),(\"P3\",np.array(P)*qv,np.array(P)**2*vv)]:
 out[name]=tests([(q[i]-q[j],v[i]+v[j]) for i,j in pairs])
out[\"financial\"]=[]
entries=[]
for c in [0,.5,2,3]:
 k=np.array(P)-c
 out[\"financial\"].append({\"cost\":c,\"v\":(k*qv).tolist(),\"v_ci\":[ci(q,v) for q,v in zip(k*qv,k*k*vv)],\"zero\":(k*q0).tolist(),\"zero_ci\":[ci(q,v) for q,v in zip(k*q0,k*k*v0)]})
 if c:entries.extend([(k[i]*qv[i]-k[j]*qv[j],k[i]**2*vv[i]+k[j]**2*vv[j]) for i,j in pairs])
out[\"P4\"]=tests(entries)
out[\"audience\"]=[]; entries=[]
for p in [7,10]:
 stats=[]
 for g in [1,0,97]:
  a=d[(d.assigned_price_gbp==p)&(d.time_pressed_family==g)];b=a[a.intent_5.isin(range(1,6))]
  rec={\"price\":p,\"group\":g,\"assigned\":base(a),\"eligible\":base(a[a.postprice_responded==1]),\"valid\":base(b)}
  if g"'!=97:
   q,v=stat(b); rec.update(q=q,ci=ci(q,v)); stats.append((q,v))
  out["audience"].append(rec)
 entries.append((stats[0][0]-stats[1][0],stats[0][1]+stats[1][1]))
out["P5"]=tests(entries)
out["niche"]=[]
for a in arms:
 a=a[a.age_band.isin([3,4])&(a.budget_band==3)&(a.current_planning_method==4)]
 out["niche"].append({"assigned":base(a),"eligible":base(a[a.postprice_responded==1]),"valid":base(a[a.intent_5.isin(range(1,6))])})
out["baseline"]={}
for col in list(d.columns[1:11])+["design_stratum","time_pressed_family"]:
 codes=sorted(d[col].unique().tolist());out["baseline"][col]={"codes":codes,"rows":[[round(a.loc[a[col]==k,"wt_design"].sum()/a.wt_design.sum(),4) for k in codes] for a in arms]}
print(json.dumps(out))
'"'"

